insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('old-oakville', 'Old Oakville', 'Oakville', 'Heritage homes and lakeside prestige.', 'Old Oakville is the town''s most prestigious address — tree-canopied streets, heritage properties, and walkable access to the harbour, downtown boutiques, and Lake Ontario. Inventory is limited and holds value through cycles.', 'Steps from the waterfront, Lakeside Park, Gairloch Gardens, and the harbour trail system.', 'Home to some of Oakville''s top-rated public schools and several private options.', 'Oakville GO is a short drive for a direct downtown Toronto commute.', 'Old Oakville Real Estate — Saigal Realty Inc., Brokerage', 'Heritage homes and lakeside prestige.', 'published', 0);
insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('glen-abbey-oakville', 'Glen Abbey', 'Oakville', 'Golf-course living and family appeal.', 'Glen Abbey is built around its namesake golf course, offering spacious family homes, mature trees, and a strong community feel across a wide range of price points — one of Oakville''s most consistently in-demand areas.', 'Extensive trails along Sixteen Mile Creek and Glen Abbey Golf Club frontage.', 'Several highly-rated public and Catholic schools serve the neighbourhood, including Abbey Park High School.', 'Close to the QEW and Highway 407, with Bronte GO a short drive.', 'Glen Abbey Real Estate — Saigal Realty Inc., Brokerage', 'Golf-course living and family appeal.', 'published', 1);
