insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('port-credit-mississauga', 'Port Credit', 'Mississauga', 'Lakeside village with a real main street.', 'Port Credit is Mississauga''s waterfront village — a walkable Lakeshore Road strip of restaurants and shops, a working marina, and a mix of century homes, semis, and new condo development around the GO station.', 'J.C. Saddington Park, the Waterfront Trail, and the Credit River mouth.', 'Served by established public and Catholic elementary schools; Port Credit Secondary is well regarded.', 'Port Credit GO offers a direct 20-minute run to Union Station.', 'Port Credit Real Estate — Saigal Realty Inc., Brokerage', 'Lakeside village with a real main street.', 'published', 0);
insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('lorne-park-mississauga', 'Lorne Park', 'Mississauga', 'Mississauga''s most prestigious address.', 'Lorne Park is Mississauga''s premier residential neighbourhood — large lots, mature tree cover, custom and estate homes, and one of the strongest school catchments in the city.', 'Close to Jack Darling Memorial Park, Rattray Marsh, and the Waterfront Trail.', 'Lorne Park Secondary is among the region''s top-ranked; elementary catchments are equally strong.', 'A short drive to Clarkson GO or Port Credit GO.', 'Lorne Park Real Estate — Saigal Realty Inc., Brokerage', 'Mississauga''s most prestigious address.', 'published', 1);
insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('mineola-mississauga', 'Mineola', 'Mississauga', 'Large lots and custom builds near the lake.', 'Mineola is a sought-after area just north and east of Port Credit, known for oversized lots, mature trees, and a steady stream of custom rebuilds — combining privacy with walkability to the village.', 'Close to the Credit River trails, Kenollie green space, and the waterfront.', 'Served by well-regarded public and Catholic schools, with Port Credit Secondary nearby.', 'Walking or short driving distance to Port Credit GO.', 'Mineola Real Estate — Saigal Realty Inc., Brokerage', 'Large lots and custom builds near the lake.', 'published', 2);
insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('clarkson-mississauga', 'Clarkson', 'Mississauga', 'Established west-end living with GO access.', 'Clarkson is a settled west Mississauga neighbourhood offering detached homes, semis, and townhomes close to Clarkson Village shops, Rattray Marsh, and one of the region''s busiest GO stations.', 'Rattray Marsh Conservation Area, Jack Darling Park, and the Waterfront Trail.', 'Served by established public and Catholic schools, including Clarkson Secondary.', 'Clarkson GO provides direct Lakeshore West service to Union.', 'Clarkson Real Estate — Saigal Realty Inc., Brokerage', 'Established west-end living with GO access.', 'published', 3);
insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('streetsville', 'Streetsville', 'Mississauga', 'Historic village inside the city.', 'Streetsville retains a genuine village main street within Mississauga — heritage buildings, independent shops, and a mix of century homes, newer infill, and townhomes along the Credit River.', 'Credit River trails, Streetsville Memorial Park, and the Vista Trail system.', 'Served by well-established public and Catholic schools, including Streetsville Secondary.', 'Streetsville GO offers Milton-line service; Highway 403 and 401 are close.', 'Streetsville Real Estate — Saigal Realty Inc., Brokerage', 'Historic village inside the city.', 'published', 4);
insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('erin-mills-mississauga', 'Erin Mills', 'Mississauga', 'Established, green, family-oriented.', 'Erin Mills is a large, well-established west Mississauga community known for its mature tree cover, ravine lots, and range of housing from townhomes to executive detached.', 'Extensive Credit River valley trails and numerous neighbourhood parks.', 'Multiple well-regarded public and Catholic schools serve the area.', 'Close to Highways 403 and 407, with Erindale GO nearby.', 'Erin Mills Real Estate — Saigal Realty Inc., Brokerage', 'Established, green, family-oriented.', 'published', 5);
insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('central-erin-mills-mississauga', 'Central Erin Mills', 'Mississauga', 'Top schools and modern family homes.', 'Central Erin Mills is one of Mississauga''s most in-demand family areas, built largely in the 1990s and known for newer detached homes and an exceptional school catchment centred on John Fraser and Thomas Street.', 'Numerous neighbourhood parks plus Credit River valley trail access.', 'John Fraser Secondary and St. Aloysius Gonzaga are among Ontario''s highest-ranked.', 'Immediate Highway 403 access and close to Highway 407.', 'Central Erin Mills Real Estate — Saigal Realty Inc., Brokerage', 'Top schools and modern family homes.', 'published', 6);
insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('churchill-meadows-mississauga', 'Churchill Meadows', 'Mississauga', 'Newer homes, strong schools, west-end value.', 'Churchill Meadows is a newer west Mississauga community of detached homes and townhomes built from the late 1990s, popular with families for its schools, community centre, and highway access.', 'Churchill Meadows Community Common and Sports Park, plus neighbourhood green space.', 'Newer, well-rated public and Catholic elementary schools serve the neighbourhood.', 'Immediate access to Highways 403 and 407.', 'Churchill Meadows Real Estate — Saigal Realty Inc., Brokerage', 'Newer homes, strong schools, west-end value.', 'published', 7);
insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('city-centre-mississauga', 'City Centre', 'Mississauga', 'Condo living at the city''s core.', 'City Centre is Mississauga''s downtown — a dense cluster of condo towers around Square One, Celebration Square, and the transit terminal, with everything walkable and the region''s largest retail concentration at the door.', 'Celebration Square, Zonta Meadows, and nearby Cooksville Creek trails.', 'Served by central Mississauga public and Catholic elementary schools.', 'Mississauga Transitway, MiWay terminal, and quick Highway 403 access.', 'City Centre Real Estate — Saigal Realty Inc., Brokerage', 'Condo living at the city''s core.', 'published', 8);
insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('cooksville-mississauga', 'Cooksville', 'Mississauga', 'Central, transit-rich, strong value.', 'Cooksville is one of Mississauga''s oldest and most centrally located neighbourhoods, offering a mix of older detached homes, rental apartments, and new condo development around the Dundas and Hurontario corridors.', 'Cooksville Creek trails and several neighbourhood parks.', 'Served by established central Mississauga public and Catholic schools.', 'Cooksville GO plus the new Hazel McCallion LRT line along Hurontario.', 'Cooksville Real Estate — Saigal Realty Inc., Brokerage', 'Central, transit-rich, strong value.', 'published', 9);
insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('applewood-mississauga', 'Applewood', 'Mississauga', 'Mature east-end neighbourhood.', 'Applewood is an established east Mississauga neighbourhood of bungalows, back-splits, and side-splits on full-sized lots with mature trees — reliable value close to Toronto''s western edge.', 'Applewood Hills Park, Etobicoke Creek trails, and neighbourhood green space.', 'Served by well-established public and Catholic elementary schools.', 'Quick access to Highways 401, 403, and the QEW; Dixie GO is nearby.', 'Applewood Real Estate — Saigal Realty Inc., Brokerage', 'Mature east-end neighbourhood.', 'published', 10);
insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('dixie-mississauga', 'Dixie', 'Mississauga', 'Employment lands and practical housing.', 'Dixie spans east Mississauga''s employment corridor and adjacent residential pockets, combining industrial and commercial property with practical, affordably-priced homes close to major highways.', 'Etobicoke Creek trail and nearby neighbourhood parks.', 'Served by established east Mississauga public and Catholic schools.', 'Dixie GO plus immediate access to Highways 401, 403, 427, and the QEW.', 'Dixie Real Estate — Saigal Realty Inc., Brokerage', 'Employment lands and practical housing.', 'published', 11);
insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('east-credit-mississauga', 'East Credit', 'Mississauga', 'Large family homes in central Mississauga.', 'East Credit is a large central Mississauga community known for spacious detached homes built in the 1980s and 1990s, with strong schools and close proximity to Heartland Town Centre.', 'Numerous neighbourhood parks plus Credit River valley trail access.', 'Multiple well-regarded public and Catholic schools serve the area.', 'Close to Highways 401 and 403, with Streetsville GO nearby.', 'East Credit Real Estate — Saigal Realty Inc., Brokerage', 'Large family homes in central Mississauga.', 'published', 12);
insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('erindale-mississauga', 'Erindale', 'Mississauga', 'Ravine lots and village character.', 'Erindale is an established central Mississauga neighbourhood along the Credit River, known for mature trees, ravine lots, and the historic Erindale village core near Dundas Street.', 'Erindale Park, the Credit River trail system, and University of Toronto Mississauga green space.', 'Served by well-established public and Catholic schools.', 'Erindale GO on the Milton line, with Highway 403 close by.', 'Erindale Real Estate — Saigal Realty Inc., Brokerage', 'Ravine lots and village character.', 'published', 13);
insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('creditview-mississauga', 'Creditview', 'Mississauga', 'Quiet streets along the Credit River.', 'Creditview is a central Mississauga neighbourhood following the Credit River corridor, offering established detached homes with ravine and green-space backing on quieter residential streets.', 'Credit River valley trails and multiple neighbourhood parks.', 'Served by well-regarded central Mississauga public and Catholic schools.', 'Close to Highways 403 and 401, with Streetsville and Erindale GO nearby.', 'Creditview Real Estate — Saigal Realty Inc., Brokerage', 'Quiet streets along the Credit River.', 'published', 14);
insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('gateway-mississauga', 'Gateway', 'Mississauga', 'Employment district near the airport.', 'Gateway is a northeast Mississauga employment area of industrial, warehouse, and office properties close to Pearson Airport — a core focus for our commercial and industrial practice.', 'Nearby Etobicoke Creek trail and Malton-area parks.', 'Adjacent residential neighbourhoods are served by northeast Mississauga schools.', 'Immediate access to Highways 401, 409, 427, and Pearson Airport.', 'Gateway Real Estate — Saigal Realty Inc., Brokerage', 'Employment district near the airport.', 'published', 15);
