insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('lakeview-mississauga', 'Lakeview', 'Mississauga', 'Lakeside neighbourhood on the rise.', 'Lakeview is an east-end lakeside Mississauga neighbourhood of bungalows and infill rebuilds, seeing significant investment as the waterfront redevelopment along Lakeshore Road progresses.', 'Lakefront Promenade Park, Marie Curtis Park, and the Waterfront Trail.', 'Served by established public and Catholic elementary schools.', 'Long Branch GO is close, with quick QEW access.', 'Lakeview Real Estate — Saigal Realty Inc., Brokerage', 'Lakeside neighbourhood on the rise.', 'published', 17);
