insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('malton-mississauga', 'Malton', 'Mississauga', 'Established value near the airport.', 'Malton is a long-established northeast Mississauga community offering some of the city''s most accessible detached-home pricing, with a strong local community and proximity to airport employment.', 'Wildwood Park, Etobicoke Creek trails, and Malton Community Centre green space.', 'Served by established public and Catholic schools, including Lincoln M. Alexander Secondary.', 'Malton GO on the Kitchener line, plus immediate 401/427/409 access.', 'Malton Real Estate — Saigal Realty Inc., Brokerage', 'Established value near the airport.', 'published', 19);
insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('mavis-erindale-mississauga', 'Mavis-Erindale', 'Mississauga', 'Central employment and commercial corridor.', 'Mavis-Erindale is a central Mississauga employment district of industrial, warehouse, and commercial properties along the Mavis Road corridor — a focus area for our commercial and investment clients.', 'Nearby Credit River valley trails and neighbourhood green space.', 'Adjacent residential neighbourhoods are served by central Mississauga schools.', 'Immediate access to Highways 403 and 401.', 'Mavis-Erindale Real Estate — Saigal Realty Inc., Brokerage', 'Central employment and commercial corridor.', 'published', 20);
insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('meadwovale-mississauga', 'Meadowvale', 'Mississauga', 'Green, established, family-friendly.', 'Meadowvale is a large northwest Mississauga community built around Lake Aquitaine and an extensive trail network, offering detached homes, townhomes, and condos with a strong outdoor character.', 'Lake Aquitaine Park, Lake Wabukayne, and extensive connected trail systems.', 'Multiple well-regarded public and Catholic schools serve the area.', 'Meadowvale GO on the Milton line, plus Highway 401 and 407 access.', 'Meadowvale Real Estate — Saigal Realty Inc., Brokerage', 'Green, established, family-friendly.', 'published', 21);
insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('meadowvale-village-mississauga', 'Meadowvale Village', 'Mississauga', 'Heritage village with executive homes.', 'Meadowvale Village is a heritage conservation district in north Mississauga, pairing preserved 19th-century village streets with newer executive homes on larger lots nearby.', 'Credit River valley trails, Meadowvale Conservation Area, and village green space.', 'Served by well-regarded north Mississauga public and Catholic schools.', 'Close to Highways 401 and 407, with Streetsville GO nearby.', 'Meadowvale Village Real Estate — Saigal Realty Inc., Brokerage', 'Heritage village with executive homes.', 'published', 22);
