insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('northeast-mississauga', 'Northeast Mississauga', 'Mississauga', 'Industrial and logistics corridor.', 'Northeast Mississauga is a major industrial and logistics district serving Pearson Airport and the GTA distribution network — primarily a commercial and investment market rather than residential.', 'Nearby Etobicoke Creek trail corridors.', 'Adjacent residential areas are served by northeast Mississauga schools.', 'Immediate access to Highways 401, 407, 409, and 427.', 'Northeast Mississauga Real Estate — Saigal Realty Inc., Brokerage', 'Industrial and logistics corridor.', 'published', 24);
insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('rathwood-mississauga', 'Rathwood', 'Mississauga', 'Established east-end family homes.', 'Rathwood is an established east Mississauga neighbourhood of detached homes, semis, and townhomes on quiet streets with mature trees, close to Rockwood Mall and major highways.', 'Burnhamthorpe Community Centre, Rathwood Park, and Etobicoke Creek trails.', 'Served by well-established public and Catholic elementary schools.', 'Quick access to Highways 403, 401, and the QEW.', 'Rathwood Real Estate — Saigal Realty Inc., Brokerage', 'Established east-end family homes.', 'published', 25);
insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('sheridan-mississauga', 'Sheridan', 'Mississauga', 'Mature homes on generous lots.', 'Sheridan is an established southwest Mississauga neighbourhood of detached homes on larger, mature lots, valued for its tree cover and proximity to both Clarkson Village and the Erin Mills corridor.', 'Sheridan Park green space, Rattray Marsh, and Credit River valley access.', 'Served by well-regarded public and Catholic schools.', 'Close to Clarkson GO, the QEW, and Highway 403.', 'Sheridan Real Estate — Saigal Realty Inc., Brokerage', 'Mature homes on generous lots.', 'published', 26);
insert into public.neighbourhoods (slug, name, city, headline, description, lifestyle, schools, commute, seo_title, seo_description, status, display_order) values ('sheridan-park', 'Sheridan Park', 'Mississauga', 'Research and corporate campus district.', 'Sheridan Park is a distinctive southwest Mississauga business park set in mature woodland, home to research facilities and corporate offices — a specialized commercial market with limited adjacent residential.', 'The park district''s own woodland setting plus nearby Rattray Marsh.', 'Surrounding Sheridan and Clarkson neighbourhoods serve families working in the park.', 'Immediate QEW access, with Clarkson GO a short drive.', 'Sheridan Park Real Estate — Saigal Realty Inc., Brokerage', 'Research and corporate campus district.', 'published', 27);
